// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, address(this).balance / 2);
        address owner = c.owner();
        uint256 before = address(c).balance;
        vm.deal(owner, 0);
        vm.deal(address(this), amount);
        (bool s, ) = address(c).call{value: amount}("");
        assertTrue(s);
        assertEq(address(c).balance, before + amount);
        vm.prank(owner);
        c.withdraw(amount);
        assertEq(address(c).balance, before, "withdraw must reduce contract balance by _value");
    }

    receive() external payable {}
}
